-- =====================================================================
-- WA9TECH — Référentiels culturels de départ : lieux, organisateurs, artistes
-- Compilés le 17/10/2026 à partir de sources publiques (portail culturel du ministère,
-- Wikipédia, programmes de festivals, presse, pages officielles). À compléter et
-- corriger dans le back-office. Idempotent : rien n'est créé en double si la ligne existe déjà
-- (même nom normalisé), et les champs déjà remplis ne sont jamais écrasés.
-- 253 lieux, 101 organisateurs, 396 artistes.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Lieux
-- ---------------------------------------------------------------------
create temporary table _lieux (ville text, nom text, nom_ar text, type public.type_lieu, adresse text, telephone text, lien text, lat double precision, lng double precision);

select v.id, t.nom, t.nom_ar, t.type, t.adresse, t.telephone, t.lien,
       case when t.lat is not null and t.lng is not null
            then extensions.st_setsrid(extensions.st_makepoint(t.lng, t.lat), 4326)::extensions.geography end
  from _lieux t
  join public.ville v on v.slug = t.ville
 where not exists (select 1 from public.lieu l
                    where l.ville_id = v.id and public.normaliser(l.nom) = public.normaliser(t.nom));

-- ---------------------------------------------------------------------
-- Organisateurs
-- ---------------------------------------------------------------------
create temporary table _orgas (nom text, description text, lien text, email text, telephone text);

select t.nom, t.description, t.lien, t.email, t.telephone
  from _orgas t
 where not exists (select 1 from public.organisateur o where public.normaliser(o.nom) = public.normaliser(t.nom));

-- ---------------------------------------------------------------------
-- Artistes (rapprochés par rapprocher_artiste : pas de doublon avec ceux déjà saisis)
-- ---------------------------------------------------------------------
create temporary table _artistes (nom text, nom_ar text, discipline text, lien text);

do $$
declare
  r record;
  v_id uuid;
begin
  for r in select * from _artistes loop
    v_id := public.rapprocher_artiste(r.nom);
    if v_id is not null then
      update public.artiste a
         set nom_ar        = coalesce(a.nom_ar, r.nom_ar),
             lien          = coalesce(a.lien, r.lien),
             discipline_id = coalesce(a.discipline_id, (select c.id from public.categorie c where c.slug = r.discipline))
       where a.id = v_id;
    end if;
  end loop;
end;
$$;

drop table _lieux, _orgas, _artistes;
